INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT156-S4-Q11$batch05$, 156, 4, 11, $batch05$Necessary Assumption$batch05$, $batch05$A law is futile unless most of the parties subject to it abide by it willingly. Thus, there can be no comprehensive international solution to the problem of pollution, since few nations would willingly give up their power over their own industries.$batch05$, $batch05$Which one of the following is an assumption required by the argument?$batch05$, $batch05$B$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$A comprehensive solution to the problems of pollution would require major changes in international law.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$Some nations would be required to give up some of their power over their own industries as part of any comprehensive solution to the problem of pollution.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$If most nations were willing to abide by international law, then there could be a comprehensive solution to the problem of pollution.$batch05$, $batch05$Reversal$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$The problems created by pollution affect most of the world’s nations, but the pollution itself is produced by the industries of relatively few nations.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$Most of the current international laws concerning pollution do not require nations to give up any of their power over their own industries.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$There can be no comprehensive international solution to pollution.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$A law is futile unless most of the parties under it obey willingly. Few nations would willingly give up power over their own industries.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The reluctance only matters if a solution would actually *ask* nations to give up that power. If a comprehensive solution could be built without touching anyone's control over their industries, nobody's reluctance would get in the way.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: any comprehensive solution would require some nations to give up some power over their industries.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Changes to international law may or may not be involved. The argument turns on giving up power over industries.$batch05$), ($batch05$B$batch05$, $batch05$Notice the "some ... some" wording: modest and exactly enough. Negate it: "a comprehensive solution would require *no* nation to give up *any* power over its industries." Then the reluctance is irrelevant, and the conclusion has no support.$batch05$), ($batch05$C$batch05$, $batch05$This says willing obedience would be enough for a solution. The argument needs the reverse: no willing obedience means no solution.$batch05$), ($batch05$D$batch05$, $batch05$Who produces the pollution and who suffers from it is never discussed.$batch05$), ($batch05$E$batch05$, $batch05$What current laws require says nothing about what a comprehensive solution would require.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT156-S4-Q11$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
